script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
 api,
 helpers
}) {
 // If field value is present in form, we read from form else from data broker
 var articleType = api.data?.record?.form?.fields?.article_type?.value || 
 api.data?.fetch_article_type?.result?.article_type?.value;


 // Hide Blocks tab if article type is wiki or markdown
 if (articleType === 'wiki' || articleType === 'markdown') {
 return true;
 }

 return !((api.context.props.table === "kb_knowledge" || api.context.props.table.startsWith("kb_template") || api.context.props.table.startsWith("u_kb_template")) && api.data.plugin_status_1.output.active);
}

